mapper.select:
SELECT w.region_id AS regionId, COUNT(DISTINCT w.id) AS warehouseCount, COALESCE(SUM(i.available_quantity), 0) AS totalAvailable, COALESCE(SUM(i.reserved_quantity), 0) AS totalReserved, COALESCE(SUM(i.in_transit_quantity), 0) AS totalInTransit, COALESCE(SUM(i.damaged_quantity), 0) AS totalDamaged FROM wms_warehouse w LEFT JOIN wms_inventory i ON i.warehouse_id = w.id
AND i.erp_tenant_id IN #{e}
WHERE w.warehouse_type = 'OWN' AND w.status = 1 AND w.region_id IN
#{id}
GROUP BY w.region_id

SELECT w.region_id AS regionId, i.sku_code AS skuCode, SUM(COALESCE(i.available_quantity, 0)) AS totalAvailable, SUM(COALESCE(i.reserved_quantity, 0)) AS totalReserved, SUM(COALESCE(i.in_transit_quantity, 0)) AS totalInTransit, SUM(COALESCE(i.damaged_quantity, 0)) AS totalDamaged FROM wms_inventory i INNER JOIN wms_warehouse w ON i.warehouse_id = w.id WHERE w.warehouse_type = 'OWN' AND w.status = 1 AND w.deleted = 0
AND w.region_id IN
#{id}
AND i.sku_code LIKE CONCAT('%', #{skuKeyword}, '%')
AND i.erp_tenant_id IN #{e}
GROUP BY w.region_id, i.sku_code

SELECT w.region_id AS regionId, i.sku_code AS skuCode, SUM(COALESCE(i.available_quantity, 0)) AS totalAvailable, SUM(COALESCE(i.reserved_quantity, 0)) AS totalReserved, SUM(COALESCE(i.in_transit_quantity, 0)) AS totalInTransit, SUM(COALESCE(i.damaged_quantity, 0)) AS totalDamaged FROM wms_inventory i INNER JOIN wms_warehouse w ON i.warehouse_id = w.id WHERE w.region_id = #{regionId} AND w.warehouse_type = 'OWN' AND w.status = 1 AND w.deleted = 0 AND i.sku_code = #{skuCode}
AND i.erp_tenant_id IN #{e}
GROUP BY w.region_id, i.sku_code
